    {
        "id": "code2-20", "name": "justify",
        "spec": "Write justify(words, width) -> list of lines. Pack words greedily into lines of exactly width characters: distribute the spaces between words as evenly as possible, giving extra spaces to the leftmost gaps first. The last line, and any line holding a single word, is left-justified with trailing spaces to reach width. Every word is shorter than or equal to width. Empty input returns [].",
        "visible": ["assert justify(['This', 'is', 'an', 'example', 'of', 'text', 'justification.'], 16) == ['This    is    an', 'example  of text', 'justification.  ']",
                    "assert justify(['a'], 3) == ['a  ']"],
        "hidden": ["assert justify([], 5) == []", "assert justify(['ab', 'cd'], 5) == ['ab cd']", "assert justify(['ab', 'cd', 'ef'], 5) == ['ab cd', 'ef   ']",
                   "assert justify(['a', 'b', 'c'], 5) == ['a b c']", "assert justify(['a', 'b', 'c', 'd'], 5) == ['a b c', 'd    ']",
                   "assert justify(['What', 'must', 'be', 'acknowledgment', 'shall', 'be'], 16) == ['What   must   be', 'acknowledgment  ', 'shall be        ']",
                   "assert justify(['x', 'yy'], 6) == ['x yy  ']", "assert all(len(l) == 7 for l in justify(['aa', 'bb', 'cc', 'dd', 'ee'], 7))"],
        "reference": "def justify(words, width):\n    lines, i = [], 0\n    while i < len(words):\n        j, length = i, len(words[i])\n        while j + 1 < len(words) and length + 1 + len(words[j + 1]) <= width:\n            j += 1; length += 1 + len(words[j])\n        chunk = words[i:j + 1]\n        if j == len(words) - 1 or len(chunk) == 1:\n            line = ' '.join(chunk)\n            lines.append(line + ' ' * (width - len(line)))\n        else:\n            gaps = len(chunk) - 1\n            total = width - sum(len(w) for w in chunk)\n            base, extra = divmod(total, gaps)\n            line = ''\n            for k, w in enumerate(chunk[:-1]):\n                line += w + ' ' * (base + (1 if k < extra else 0))\n            lines.append(line + chunk[-1])\n        i = j + 1\n    return lines\n",
    },
